import React, { useState, useEffect } from 'react';

// Fallback blog posts matching the actual site structure
const FALLBACK_POSTS = [
  {
    id: 1,
    title: { rendered: 'The Future of AI in Digital Strategy' },
    excerpt: { rendered: '<p>Exploring how artificial intelligence is revolutionizing business strategies and creating unprecedented opportunities for growth.</p>' },
    date: '2024-03-15',
    link: 'https://pankajbiswas.com',
    _category: 'Technology',
    _readTime: '5 min read',
    _image: 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=500&h=300&fit=crop',
  },
  {
    id: 2,
    title: { rendered: 'Building Scalable Web Applications' },
    excerpt: { rendered: '<p>Best practices and architectural patterns for developing web applications that can scale with your business growth.</p>' },
    date: '2024-03-12',
    link: 'https://pankajbiswas.com',
    _category: 'Development',
    _readTime: '7 min read',
    _image: 'https://images.unsplash.com/photo-1460925895917-adf4e565db8d?w=500&h=300&fit=crop',
  },
  // Add more fallback posts here...
];

const Blogs = () => {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const postsPerPage = 12;

  useEffect(() => {
    const fetchPosts = async () => {
      try {
        // Fetch posts from WordPress via dev proxy (or relative natively in prod)
        const response = await fetch(
          `/wp-json/wp/v2/posts?per_page=${postsPerPage}&_embed=1&orderby=date&order=desc&page=${currentPage}`
        );

        if (!response.ok) {
          throw new Error('Failed to fetch posts');
        }

        const data = await response.json();
        setPosts(data);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching posts:', error);
        setPosts(FALLBACK_POSTS); // Fallback data
        setError(true);
        setLoading(false);
      }
    };

    fetchPosts();
  }, [currentPage]);

  const goToPage = (page) => {
    if (page >= 1) {
      setCurrentPage(page);
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
    <>
      <section className="blogs-section">
        <div className="container">
          {loading ? (
            <p>Loading blog posts...</p>
          ) : error ? (
            <p>Error loading blog posts. Displaying fallback content.</p>
          ) : (
            posts.map((post) => (
              <div key={post.id} className="blog-card">
                <img src={post._image} alt={post.title.rendered} />
                <h2>{post.title.rendered}</h2>
                <div dangerouslySetInnerHTML={{ __html: post.excerpt.rendered }} />
                <a href={post.link} target="_blank" rel="noopener noreferrer">Read more</a>
              </div>
            ))
          )}

          {/* Pagination */}
          <nav className="pagination-nav">
            <button
              onClick={() => goToPage(Math.max(currentPage - 1, 1))}
              disabled={currentPage === 1}
            >
              ‹ Previous
            </button>
            {Array.from({ length: 5 }, (_, i) => i + 1).map((pg) => (
              <button
                key={pg}
                onClick={() => goToPage(pg)}
                style={{
                  background: currentPage === pg ? '#d4af37' : 'transparent',
                  border: '1px solid rgba(212,175,55,0.3)',
                  color: currentPage === pg ? '#0d0d0d' : '#d4af37',
                  padding: '0.5rem 0.9rem',
                  cursor: 'pointer',
                }}
              >
                {pg}
              </button>
            ))}
            <button
              onClick={() => goToPage(currentPage + 1)}
              disabled={currentPage === 5}
            >
              Next ›
            </button>
          </nav>
        </div>
      </section>

      {/* Call to Action */}
      <section className="cta-luxury">
        <div className="container">
          <div className="cta-content">
            <h2>Ready to Transform Your Digital Future?</h2>
            <p>Let’s discuss your vision and create a strategic roadmap for unprecedented growth.</p>
            <a href="/contact" className="btn btn-gold btn-lg">Schedule Free Strategy Call</a>
          </div>
        </div>
      </section>
    </>
  );
};

export default Blogs;
